1	import { Router, type Request } from "express";
2	import type { Db } from "@paperclipai/db";
3	import {
4	  DEFAULT_FEEDBACK_DATA_SHARING_TERMS_VERSION,
5	  companyPortabilityExportSchema,
6	  companyPortabilityImportSchema,
7	  companyPortabilityPreviewSchema,
8	  createCompanySchema,
9	  feedbackTargetTypeSchema,
10	  feedbackTraceStatusSchema,
11	  feedbackVoteValueSchema,
12	  updateCompanyBrandingSchema,
13	  updateCompanySchema,
14	} from "@paperclipai/shared";
15	import { badRequest, forbidden } from "../errors.js";
16	import { validate } from "../middleware/validate.js";
17	import {
18	  accessService,
19	  agentService,
20	  budgetService,
21	  companyPortabilityService,
22	  companyService,
23	  feedbackService,
24	  logActivity,
25	} from "../services/index.js";
26	import type { StorageService } from "../storage/types.js";
27	import { assertBoard, assertCompanyAccess, assertInstanceAdmin, getActorInfo } from "./authz.js";
28	import type { Handler } from "../http/types.js";
29	import { expressHandler } from "../http/express-adapter.js";
30	
31	export function companyRoutes(db: Db, storage?: StorageService) {
32	  const router = Router();
33	  const svc = companyService(db);
34	  const agents = agentService(db);
35	  const portability = companyPortabilityService(db, storage);
36	  const access = accessService(db);
37	  const budgets = budgetService(db);
38	  const feedback = feedbackService(db);
39	
40	  function parseBooleanQuery(value: unknown) {
41	    return value === true || value === "true" || value === "1";
42	  }
43	
44	  function parseDateQuery(value: unknown, field: string) {
45	    if (typeof value !== "string" || value.trim().length === 0) return undefined;
46	    const parsed = new Date(value);
47	    if (Number.isNaN(parsed.getTime())) {
48	      throw badRequest(`Invalid ${field} query value`);
49	    }
50	    return parsed;
51	  }
52	
53	  function assertImportTargetAccess(
54	    req: Request,
55	    target: { mode: "new_company" } | { mode: "existing_company"; companyId: string },
56	  ) {
57	    if (target.mode === "new_company") {
58	      assertInstanceAdmin(req);
59	      return;
60	    }
61	    assertCompanyAccess(req, target.companyId);
62	  }
63	
64	  async function assertCanUpdateBranding(req: Request, companyId: string) {
65	    assertCompanyAccess(req, companyId);
66	    if (req.actor.type === "board") return;
67	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
68	
69	    const actorAgent = await agents.getById(req.actor.agentId);
70	    if (!actorAgent || actorAgent.companyId !== companyId) {
71	      throw forbidden("Agent key cannot access another company");
72	    }
73	    if (actorAgent.role !== "ceo") {
74	      throw forbidden("Only CEO agents can update company branding");
75	    }
76	  }
77	
78	  async function assertCanManagePortability(req: Request, companyId: string, capability: "imports" | "exports") {
79	    assertCompanyAccess(req, companyId);
80	    if (req.actor.type === "board") return;
81	    if (!req.actor.agentId) throw forbidden("Agent authentication required");
82	
83	    const actorAgent = await agents.getById(req.actor.agentId);
84	    if (!actorAgent || actorAgent.companyId !== companyId) {
85	      throw forbidden("Agent key cannot access another company");
86	    }
87	    if (actorAgent.role !== "ceo") {
88	      throw forbidden(`Only CEO agents can manage company ${capability}`);
89	    }
90	  }
91	
92	  // Storage sentinel used for handlers that do not touch storage.
93	  const storageSentinel = new Proxy({} as StorageService, {
94	    get(_target, prop) {
95	      throw new Error(`company handler unexpectedly accessed storage.${String(prop)}`);
96	    },
97	  });
98	
99	  const listCompanies: Handler = async (ctx) => {
100	    const req = ctx as unknown as Request;
101	    assertBoard(req);
102	    const result = await svc.list();
103	    if (req.actor.source === "local_implicit" || req.actor.isInstanceAdmin) {
104	      return Response.json(result);
105	    }
106	    const allowed = new Set(req.actor.companyIds ?? []);
107	    return Response.json(result.filter((company) => allowed.has(company.id)));
108	  };
109	
110	  const getCompanyStats: Handler = async (ctx) => {
111	    const req = ctx as unknown as Request;
112	    assertBoard(req);
113	    const allowed = req.actor.source === "local_implicit" || req.actor.isInstanceAdmin
114	      ? null
115	      : new Set(req.actor.companyIds ?? []);
116	    const stats = await svc.stats();
117	    if (!allowed) {
118	      return Response.json(stats);
119	    }
120	    const filtered = Object.fromEntries(Object.entries(stats).filter(([companyId]) => allowed.has(companyId)));
121	    return Response.json(filtered);
122	  };
123	
124	  const missingCompanyIdError: Handler = async (_ctx) => {
125	    return Response.json(
126	      { error: "Missing companyId in path. Use /api/companies/{companyId}/issues." },
127	      { status: 400 },
128	    );
129	  };
130	
131	  const getCompany: Handler = async (ctx) => {
132	    const req = ctx as unknown as Request;
133	    const companyId = ctx.param("companyId")!;
134	    assertCompanyAccess(req, companyId);
135	    // Allow agents (CEO) to read their own company; board always allowed
136	    if (req.actor.type !== "agent") {
137	      assertBoard(req);
138	    }
139	    const company = await svc.getById(companyId);
140	    if (!company) {
141	      return Response.json({ error: "Company not found" }, { status: 404 });
142	    }
143	    return Response.json(company);
144	  };
145	
146	  const listFeedbackTraces: Handler = async (ctx) => {
147	    const req = ctx as unknown as Request;
148	    const companyId = ctx.param("companyId")!;
149	    assertCompanyAccess(req, companyId);
150	    assertBoard(req);
151	
152	    const targetTypeRaw = ctx.query("targetType");
153	    const voteRaw = ctx.query("vote");
154	    const statusRaw = ctx.query("status");
155	    const issueIdRaw = ctx.query("issueId");
156	    const issueId = issueIdRaw && issueIdRaw.trim().length > 0 ? issueIdRaw : undefined;
157	    const projectIdRaw = ctx.query("projectId");
158	    const projectId = projectIdRaw && projectIdRaw.trim().length > 0 ? projectIdRaw : undefined;
159	    const fromRaw = ctx.query("from");
160	    const toRaw = ctx.query("to");
161	    const sharedOnlyRaw = ctx.query("sharedOnly");
162	    const includePayloadRaw = ctx.query("includePayload");
163	
164	    const traces = await feedback.listFeedbackTraces({
165	      companyId,
166	      issueId,
167	      projectId,
168	      targetType: targetTypeRaw ? feedbackTargetTypeSchema.parse(targetTypeRaw) : undefined,
169	      vote: voteRaw ? feedbackVoteValueSchema.parse(voteRaw) : undefined,
170	      status: statusRaw ? feedbackTraceStatusSchema.parse(statusRaw) : undefined,
171	      from: parseDateQuery(fromRaw, "from"),
172	      to: parseDateQuery(toRaw, "to"),
173	      sharedOnly: parseBooleanQuery(sharedOnlyRaw),
174	      includePayload: parseBooleanQuery(includePayloadRaw),
175	    });
176	    return Response.json(traces);
177	  };
178	
179	  const exportCompany: Handler = async (ctx) => {
180	    const req = ctx as unknown as Request;
181	    const companyId = ctx.param("companyId")!;
182	    await assertCanManagePortability(req, companyId, "exports");
183	    const body = await ctx.json();
184	    const result = await portability.exportBundle(companyId, body);
185	    return Response.json(result);
186	  };
187	
188	  const previewImport: Handler = async (ctx) => {
189	    const req = ctx as unknown as Request;
190	    assertBoard(req);
191	    const body = await ctx.json<{ target: Parameters<typeof assertImportTargetAccess>[1] }>();
192	    assertImportTargetAccess(req, body.target);
193	    const preview = await portability.previewImport(body);
194	    return Response.json(preview);
195	  };
196	
197	  const importBundle: Handler = async (ctx) => {
198	    const req = ctx as unknown as Request;
199	    assertBoard(req);
200	    const body = await ctx.json<{ target: Parameters<typeof assertImportTargetAccess>[1]; include?: unknown }>();
201	    assertImportTargetAccess(req, body.target);
202	    const actor = getActorInfo(req);
203	    const result = await portability.importBundle(body, req.actor.type === "board" ? req.actor.userId : null);
204	    await logActivity(db, {
205	      companyId: result.company.id,
206	      actorType: actor.actorType,
207	      actorId: actor.actorId,
208	      action: "company.imported",
209	      entityType: "company",
210	      entityId: result.company.id,
211	      agentId: actor.agentId,
212	      runId: actor.runId,
213	      details: {
214	        include: body.include ?? null,
215	        agentCount: result.agents.length,
216	        warningCount: result.warnings.length,
217	        companyAction: result.company.action,
218	      },
219	    });
220	    return Response.json(result);
221	  };
222	
223	  const previewExportByCompany: Handler = async (ctx) => {
224	    const req = ctx as unknown as Request;
225	    const companyId = ctx.param("companyId")!;
226	    await assertCanManagePortability(req, companyId, "exports");
227	    const body = await ctx.json();
228	    const preview = await portability.previewExport(companyId, body);
229	    return Response.json(preview);
230	  };
231	
232	  const exportByCompany: Handler = async (ctx) => {
233	    const req = ctx as unknown as Request;
234	    const companyId = ctx.param("companyId")!;
235	    await assertCanManagePortability(req, companyId, "exports");
236	    const body = await ctx.json();
237	    const result = await portability.exportBundle(companyId, body);
238	    return Response.json(result);
239	  };
240	
241	  const previewImportByCompany: Handler = async (ctx) => {
242	    const req = ctx as unknown as Request;
243	    const companyId = ctx.param("companyId")!;
244	    await assertCanManagePortability(req, companyId, "imports");
245	    const body = await ctx.json<{ target: { mode: string; companyId?: string }; collisionStrategy?: string }>();
246	    if (body.target.mode === "existing_company" && body.target.companyId !== companyId) {
247	      throw forbidden("Safe import route can only target the route company");
248	    }
249	    if (body.collisionStrategy === "replace") {
250	      throw forbidden("Safe import route does not allow replace collision strategy");
251	    }
252	    const preview = await portability.previewImport(body, {
253	      mode: "agent_safe",
254	      sourceCompanyId: companyId,
255	    });
256	    return Response.json(preview);
257	  };
258	
259	  const applyImportByCompany: Handler = async (ctx) => {
260	    const req = ctx as unknown as Request;
261	    const companyId = ctx.param("companyId")!;
262	    await assertCanManagePortability(req, companyId, "imports");
263	    const body = await ctx.json<{ target: { mode: string; companyId?: string }; collisionStrategy?: string; include?: unknown }>();
264	    if (body.target.mode === "existing_company" && body.target.companyId !== companyId) {
265	      throw forbidden("Safe import route can only target the route company");
266	    }
267	    if (body.collisionStrategy === "replace") {
268	      throw forbidden("Safe import route does not allow replace collision strategy");
269	    }
270	    const actor = getActorInfo(req);
271	    const result = await portability.importBundle(body, req.actor.type === "board" ? req.actor.userId : null, {
272	      mode: "agent_safe",
273	      sourceCompanyId: companyId,
274	    });
275	    await logActivity(db, {
276	      companyId: result.company.id,
277	      actorType: actor.actorType,
278	      actorId: actor.actorId,
279	      entityType: "company",
280	      entityId: result.company.id,
281	      agentId: actor.agentId,
282	      runId: actor.runId,
283	      action: "company.imported",
284	      details: {
285	        include: body.include ?? null,
286	        agentCount: result.agents.length,
287	        warningCount: result.warnings.length,
288	        companyAction: result.company.action,
289	        importMode: "agent_safe",
290	      },
291	    });
292	    return Response.json(result);
293	  };
294	
295	  const createCompany: Handler = async (ctx) => {
296	    const req = ctx as unknown as Request;
297	    assertBoard(req);
298	    if (!(req.actor.source === "local_implicit" || req.actor.isInstanceAdmin)) {
299	      throw forbidden("Instance admin required");
300	    }
301	    const body = await ctx.json();
302	    const company = await svc.create(body);
303	    await access.ensureMembership(company.id, "user", req.actor.userId ?? "local-board", "owner", "active");
304	    await logActivity(db, {
305	      companyId: company.id,
306	      actorType: "user",
307	      actorId: req.actor.userId ?? "board",
308	      action: "company.created",
309	      entityType: "company",
310	      entityId: company.id,
311	      details: { name: company.name },
312	    });
313	    if (company.budgetMonthlyCents > 0) {
314	      await budgets.upsertPolicy(
315	        company.id,
316	        {
317	          scopeType: "company",
318	          scopeId: company.id,
319	          amount: company.budgetMonthlyCents,
320	          windowKind: "calendar_month_utc",
321	        },
322	        req.actor.userId ?? "board",
323	      );
324	    }
325	    return Response.json(company, { status: 201 });
326	  };
327	
328	  const updateCompany: Handler = async (ctx) => {
329	    const req = ctx as unknown as Request;
330	    const companyId = ctx.param("companyId")!;
331	    assertCompanyAccess(req, companyId);
332	
333	    const actor = getActorInfo(req);
334	    const existingCompany = await svc.getById(companyId);
335	    if (!existingCompany) {
336	      return Response.json({ error: "Company not found" }, { status: 404 });
337	    }
338	    let body: Record<string, unknown>;
339	
340	    if (req.actor.type === "agent") {
341	      // Only CEO agents may update company branding fields
342	      const agentSvc = agentService(db);
343	      const actorAgent = req.actor.agentId ? await agentSvc.getById(req.actor.agentId) : null;
344	      if (!actorAgent || actorAgent.role !== "ceo") {
345	        throw forbidden("Only CEO agents or board users may update company settings");
346	      }
347	      if (actorAgent.companyId !== companyId) {
348	        throw forbidden("Agent key cannot access another company");
349	      }
350	      body = updateCompanyBrandingSchema.parse(await ctx.json());
351	    } else {
352	      assertBoard(req);
353	      body = updateCompanySchema.parse(await ctx.json());
354	
355	      if (body.feedbackDataSharingEnabled === true && !existingCompany.feedbackDataSharingEnabled) {
356	        body = {
357	          ...body,
358	          feedbackDataSharingConsentAt: new Date(),
359	          feedbackDataSharingConsentByUserId: req.actor.userId ?? "local-board",
360	          feedbackDataSharingTermsVersion:
361	            typeof body.feedbackDataSharingTermsVersion === "string" && body.feedbackDataSharingTermsVersion.length > 0
362	              ? body.feedbackDataSharingTermsVersion
363	              : DEFAULT_FEEDBACK_DATA_SHARING_TERMS_VERSION,
364	        };
365	      }
366	    }
367	
368	    const company = await svc.update(companyId, body);
369	    if (!company) {
370	      return Response.json({ error: "Company not found" }, { status: 404 });
371	    }
372	    await logActivity(db, {
373	      companyId,
374	      actorType: actor.actorType,
375	      actorId: actor.actorId,
376	      agentId: actor.agentId,
377	      runId: actor.runId,
378	      action: "company.updated",
379	      entityType: "company",
380	      entityId: companyId,
381	      details: body,
382	    });
383	    return Response.json(company);
384	  };
385	
386	  const updateCompanyBranding: Handler = async (ctx) => {
387	    const req = ctx as unknown as Request;
388	    const companyId = ctx.param("companyId")!;
389	    await assertCanUpdateBranding(req, companyId);
390	    const body = await ctx.json();
391	    const company = await svc.update(companyId, body);
392	    if (!company) {
393	      return Response.json({ error: "Company not found" }, { status: 404 });
394	    }
395	    const actor = getActorInfo(req);
396	    await logActivity(db, {
397	      companyId,
398	      actorType: actor.actorType,
399	      actorId: actor.actorId,
400	      agentId: actor.agentId,
401	      runId: actor.runId,
402	      action: "company.branding_updated",
403	      entityType: "company",
404	      entityId: companyId,
405	      details: body,
406	    });
407	    return Response.json(company);
408	  };
409	
410	  const archiveCompany: Handler = async (ctx) => {
411	    const req = ctx as unknown as Request;
412	    assertBoard(req);
413	    const companyId = ctx.param("companyId")!;
414	    assertCompanyAccess(req, companyId);
415	    const company = await svc.archive(companyId);
416	    if (!company) {
417	      return Response.json({ error: "Company not found" }, { status: 404 });
418	    }
419	    await logActivity(db, {
420	      companyId,
421	      actorType: "user",
422	      actorId: req.actor.userId ?? "board",
423	      action: "company.archived",
424	      entityType: "company",
425	      entityId: companyId,
426	    });
427	    return Response.json(company);
428	  };
429	
430	  const deleteCompany: Handler = async (ctx) => {
431	    const req = ctx as unknown as Request;
432	    assertBoard(req);
433	    const companyId = ctx.param("companyId")!;
434	    assertCompanyAccess(req, companyId);
435	    const company = await svc.remove(companyId);
436	    if (!company) {
437	      return Response.json({ error: "Company not found" }, { status: 404 });
438	    }
439	    return Response.json({ ok: true });
440	  };
441	
442	  // The storage dep is optional on this route factory; pass it when available,
443	  // otherwise use a sentinel so expressHandler's AdapterDeps type is satisfied.
444	  const storageDep = storage ?? storageSentinel;
445	
446	  router.get("/", expressHandler(listCompanies, { db, storage: storageSentinel }));
447	  router.get("/stats", expressHandler(getCompanyStats, { db, storage: storageSentinel }));
448	  // Common malformed path when companyId is empty in "/api/companies/{companyId}/issues".
449	  router.get("/issues", expressHandler(missingCompanyIdError, { db, storage: storageSentinel }));
450	  router.get("/:companyId", expressHandler(getCompany, { db, storage: storageSentinel }));
451	  router.get("/:companyId/feedback-traces", expressHandler(listFeedbackTraces, { db, storage: storageSentinel }));
452	  router.post("/:companyId/export", validate(companyPortabilityExportSchema), expressHandler(exportCompany, { db, storage: storageDep }));
453	  router.post("/import/preview", validate(companyPortabilityPreviewSchema), expressHandler(previewImport, { db, storage: storageDep }));
454	  router.post("/import", validate(companyPortabilityImportSchema), expressHandler(importBundle, { db, storage: storageDep }));
455	  router.post("/:companyId/exports/preview", validate(companyPortabilityExportSchema), expressHandler(previewExportByCompany, { db, storage: storageDep }));
456	  router.post("/:companyId/exports", validate(companyPortabilityExportSchema), expressHandler(exportByCompany, { db, storage: storageDep }));
457	  router.post("/:companyId/imports/preview", validate(companyPortabilityPreviewSchema), expressHandler(previewImportByCompany, { db, storage: storageDep }));
458	  router.post("/:companyId/imports/apply", validate(companyPortabilityImportSchema), expressHandler(applyImportByCompany, { db, storage: storageDep }));
459	  router.post("/", validate(createCompanySchema), expressHandler(createCompany, { db, storage: storageSentinel }));
460	  router.patch("/:companyId", expressHandler(updateCompany, { db, storage: storageSentinel }));
461	  router.patch("/:companyId/branding", validate(updateCompanyBrandingSchema), expressHandler(updateCompanyBranding, { db, storage: storageSentinel }));
462	  router.post("/:companyId/archive", expressHandler(archiveCompany, { db, storage: storageSentinel }));
463	  router.delete("/:companyId", expressHandler(deleteCompany, { db, storage: storageSentinel }));
464	
465	  return router;
466	}
